<?php

declare(strict_types=1);
require __DIR__ . DIRECTORY_SEPARATOR . 'config.php';
$admin = require_admin();
$error = '';
$notice = (string) ($_GET['notice'] ?? '');
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'course_access') {
    try {
        $userId = trim((string) ($_POST['user_id'] ?? ''));
        $courseSlug = trim((string) ($_POST['course'] ?? ''));
        $active = (string) ($_POST['access'] ?? '') === 'restore';
        if ($userId === '' || $courseSlug === '') throw new RuntimeException('Select a user and course.');
        admin_set_course_access($userId, $courseSlug, $active, (string) $admin['id'], (string) ($_POST['reason'] ?? ''));
        header('Location: admin-course-control.php?notice=' . rawurlencode($active ? 'Course access restored.' : 'Course access deactivated.'));
        exit;
    } catch (Throwable $exception) { $error = $exception->getMessage(); }
}
$rows = admin_course_control_rows();
$catalog = published_banking_catalog();
$totalCourses = count($catalog);
$totalUsers = count($rows);
$totalPremium = count(array_filter($rows, static fn(array $row): bool => $row['premium'] !== null));
$totalEnrollments = 0;
$totalAttempts = 0;
foreach ($rows as $row) { $totalEnrollments += count(array_filter($row['courses'], static fn(array $course): bool => $course['active'])); foreach ($row['courses'] as $course) $totalAttempts += (int) $course['attempts']; }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Course access control | Admin</title><style>:root{--navy:#16233f;--maroon:#9c3b2e;--paper:#efece2;--card:#f8f6ee;--ink:#1c1a15;--muted:#625e50;--line:#cfc7ac;--gold:#a97a24;--green:#286447;--red:#70251c}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px Arial,sans-serif}header{background:var(--navy);border-bottom:3px solid var(--gold);padding:16px 5%;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{font:700 1.45rem Georgia,serif;color:#fff;text-decoration:none}.nav{display:flex;gap:16px;flex-wrap:wrap}.nav a{color:#f5ead2;text-decoration:none}.wrap{width:min(1320px,calc(100% - 32px));margin:auto;padding:34px 0 70px}h1,h2,h3{font-family:Georgia,serif;color:var(--navy)}h1{font-size:clamp(2rem,4vw,3.1rem);margin:0 0 8px}.muted{color:var(--muted)}.intro{margin-bottom:24px}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:20px 0 28px}.stat,.panel,.user-card{background:var(--card);border:1px solid var(--line)}.stat{padding:16px}.stat strong{display:block;color:var(--maroon);font:700 1.7rem Georgia,serif}.stat span{color:var(--muted);font-size:.78rem}.notice,.error{padding:12px;margin:14px 0}.notice{background:#e0f0e6;color:#174b32}.error{background:#f7ded8;color:var(--red)}.user-list{display:grid;gap:16px}.user-card{padding:20px}.user-head{display:flex;justify-content:space-between;align-items:start;gap:18px;border-bottom:1px solid var(--line);padding-bottom:14px}.user-head h2{margin:0 0 5px;font-size:1.3rem}.pill{display:inline-block;padding:4px 8px;background:#e0f0e6;color:var(--green);font-size:.72rem;font-weight:700}.pill.off{background:#f0e6df;color:var(--red)}.premium{color:var(--maroon);font-weight:700}.course-table{width:100%;border-collapse:collapse;margin-top:15px}.course-table th,.course-table td{text-align:left;padding:10px 8px;border-top:1px solid var(--line);vertical-align:middle}.course-table th{color:var(--muted);font-size:.72rem;text-transform:uppercase}.course-table small{display:block;color:var(--muted);margin-top:3px}.btn{border:0;background:var(--maroon);color:#fff;padding:8px 11px;font-weight:700;cursor:pointer}.btn.restore{background:var(--green)}.btn:disabled{opacity:.55;cursor:not-allowed}.empty{padding:25px;color:var(--muted);background:var(--card);border:1px dashed var(--line)}@media(max-width:900px){.stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.stats{grid-template-columns:repeat(2,1fr)}.wrap{padding-top:25px}.user-head{display:block}.user-head .pill{margin-top:10px}.course-table{display:block;overflow-x:auto;white-space:nowrap}.course-table td:last-child{white-space:normal;min-width:150px}}
</style></head><body><header><a class="brand" href="admin.php">RankSetu Admin</a><nav class="nav"><a href="admin.php">Control centre</a><a href="admin-subscriptions.php">Subscriptions</a><a href="admin-coupons.php">Coupons</a><a href="dashboard.php">Student view</a><a href="logout.php">Log out</a></nav></header><main class="wrap"><div class="intro"><h1>Course access control</h1><p class="muted">Monitor users, premium membership, course access and performance. Deactivation is reversible and never deletes financial or attempt history.</p></div><?php if($notice!==''): ?><div class="notice"><?= e($notice) ?></div><?php endif; ?><?php if($error!==''): ?><div class="error"><?= e($error) ?></div><?php endif; ?><section class="stats"><div class="stat"><strong><?= $totalUsers ?></strong><span>users</span></div><div class="stat"><strong><?= $totalCourses ?></strong><span>published courses</span></div><div class="stat"><strong><?= $totalEnrollments ?></strong><span>active enrollments</span></div><div class="stat"><strong><?= $totalPremium ?></strong><span>premium users</span></div><div class="stat"><strong><?= $totalAttempts ?></strong><span>submitted attempts</span></div></section><section class="user-list"><?php if($rows===[]): ?><div class="empty">No users found.</div><?php else: foreach($rows as $row): ?><article class="user-card"><div class="user-head"><div><h2><?= e($row['name']) ?></h2><div class="muted"><?= e($row['email']) ?> · <?= $row['orders'] ?> orders</div></div><div><?php if($row['premium']!==null): ?><span class="premium">Premium: <?= e((string)($row['premium']['plan_name']??'Bank Premium')) ?></span><small class="muted"> until <?= e(date('d M Y',strtotime((string)$row['premium']['expires_at']))) ?></small><?php else: ?><span class="pill">No active premium</span><?php endif; ?></div></div><?php if($row['courses']===[]): ?><p class="muted">No course activity recorded.</p><?php else: ?><table class="course-table"><thead><tr><th>Course</th><th>Access</th><th>Attempts</th><th>Average</th><th>Last attempt</th><th>Admin action</th></tr></thead><tbody><?php foreach($row['courses'] as $course): ?><tr><td><?= e((string)($catalog[$course['slug']]['title']??$course['slug'])) ?><small><?= e($course['slug']) ?></small></td><td><span class="pill <?= $course['active']?'':'off' ?>"><?= $course['active']?'Active':'Revoked' ?></span></td><td><?= (int)$course['attempts'] ?></td><td><?= (int)$course['average'] ?>%</td><td><?= $course['last']===null?'None':e(date('d M Y H:i',strtotime((string)$course['last']))) ?></td><td><form method="post" onsubmit="return confirm('<?= $course['active']?'Deactivate':'Restore' ?> this course access? Existing attempts and orders will be preserved.')"><input type="hidden" name="action" value="course_access"><input type="hidden" name="user_id" value="<?= e($row['id']) ?>"><input type="hidden" name="course" value="<?= e($course['slug']) ?>"><input type="hidden" name="access" value="<?= $course['active']?'revoke':'restore' ?>"><input type="hidden" name="reason" value="Admin course access change"><button class="btn <?= $course['active']?'':'restore' ?>" type="submit"><?= $course['active']?'Deactivate':'Restore' ?></button></form></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></article><?php endforeach; endif; ?></section></main></body></html>
